MUserData* WidgetShowcaseDrawOverride::prepareForDraw(const MDagPath& objPath,
                              const MDagPath& cameraPath,
                              const MHWRender::MFrameContext& frameContext,
                              MUserData* oldData) {
    (void)frameContext;
    WidgetShowcaseData* data = dynamic_cast<WidgetShowcaseData*>(oldData);
    if (!data) data = new WidgetShowcaseData();
    WidgetShowcaseInputs inp;
    inp.timeVal = MAnimControl::currentTime().value();
    inp.wallClock = 0.0;  // wall-clock animation deferred (deterministic)
    inp.hovered = false;  // passive hover deferred (no headless equivalent)
    // --- selection state (MGeometryUtilities + active-list fallback) ---
    MHWRender::DisplayStatus _st = MHWRender::MGeometryUtilities::displayStatus(objPath);
    inp.isLead = (_st == MHWRender::kLead);
    bool _active = (_st == MHWRender::kActive);
    inp.selected = inp.isLead || _active;
    MColor _wc = MHWRender::MGeometryUtilities::wireframeColor(objPath);
    inp.selColor[0] = _wc.r; inp.selColor[1] = _wc.g;
    inp.selColor[2] = _wc.b; inp.selColor[3] = _wc.a;
    if (!inp.selected) {
        MSelectionList _al; MGlobal::getActiveSelectionList(_al);
        if (_al.length()) {
            bool _hit = _al.hasItem(objPath);
            if (!_hit) { MDagPath _tp(objPath); _tp.pop(); _hit = _al.hasItem(_tp); }
            if (_hit) inp.selected = true;
        }
    }
    // --- camera position in the locator's local frame (backface cull) ---
    MMatrix _camW = cameraPath.inclusiveMatrix();
    MMatrix _objWInv = objPath.inclusiveMatrixInverse();
    MPoint _camLocal = MPoint(_camW(3,0), _camW(3,1), _camW(3,2)) * _objWInv;
    data->viewPosLocal[0] = _camLocal.x;
    data->viewPosLocal[1] = _camLocal.y;
    data->viewPosLocal[2] = _camLocal.z;
    // --- local text scale: screen pixels per OBJECT unit at the node's depth.
    //     Port of draw_buffers.pixels_per_world_unit * matrix_uniform_scale:
    //     project a 1-unit probe along the camera up axis at the object origin
    //     through world->clip and read the NDC delta in pixels. 0 when the
    //     view is unavailable (headless) -> text sizes are taken as pixels.
    data->localPpu = 0.0;
    { MStatus _fs;
      const MMatrix _vp = frameContext.getMatrix(MHWRender::MFrameContext::kViewProjMtx, &_fs);
      int _vx = 0, _vy = 0, _vw = 0, _vh = 0;
      frameContext.getViewportDimensions(_vx, _vy, _vw, _vh);
      const MMatrix _ow = objPath.inclusiveMatrix();
      MVector _up(_camW(1,0), _camW(1,1), _camW(1,2));   // camera up axis (row 1)
      const double _un = _up.length();
      if (_fs == MS::kSuccess && _vh > 0 && _un > 1e-12) {
          _up /= _un;
          const MPoint _a(_ow(3,0), _ow(3,1), _ow(3,2));
          const MPoint _b = _a + _up;                       // ref_len 1.0
          // row-vector world->clip; only (y, w) are needed
          const double _cyA = _a.x*_vp(0,1) + _a.y*_vp(1,1) + _a.z*_vp(2,1) + _vp(3,1);
          const double _cwA = _a.x*_vp(0,3) + _a.y*_vp(1,3) + _a.z*_vp(2,3) + _vp(3,3);
          const double _cyB = _b.x*_vp(0,1) + _b.y*_vp(1,1) + _b.z*_vp(2,1) + _vp(3,1);
          const double _cwB = _b.x*_vp(0,3) + _b.y*_vp(1,3) + _b.z*_vp(2,3) + _vp(3,3);
          if (_cwA > 1e-9 && _cwB > 1e-9) {
              const double _ppw = std::fabs(_cyB / _cwB - _cyA / _cwA) * 0.5 * (double)_vh;
              const double _sx = MVector(_ow(0,0), _ow(0,1), _ow(0,2)).length();
              const double _sy = MVector(_ow(1,0), _ow(1,1), _ow(1,2)).length();
              const double _sz = MVector(_ow(2,0), _ow(2,1), _ow(2,2)).length();
              const double _prod = _sx * _sy * _sz;
              data->localPpu = _ppw * ((_prod > 0.0) ? std::cbrt(_prod) : 1.0);
          }
      }
    }
    // --- user input plugs ---
    MFnDependencyNode fn(objPath.node());
    { MStatus _ms; MPlug _p = fn.findPlug("preset", false, &_ms);
      if (_ms == MS::kSuccess && !_p.isNull()) inp.in_preset = _p.asShort(); }
    WidgetShowcase_computeBuffers(inp, *data);
    data->selected = inp.selected;
    data->selColor = MColor(inp.selColor[0], inp.selColor[1], inp.selColor[2], inp.selColor[3]);
    return data;
}

// Selection tint: Maya's wireframe color over the element's OWN alpha
// (port of MPyLocatorDrawOverride._tinted -- the highlight changes what
// color a drawing is, not how much you can see through it).
static inline MColor _selTint(const MColor& sel, const MColor& own) {
    return MColor(sel.r, sel.g, sel.b, own.a);
}

// Draw ONE polygon soup (fill: fan-triangulate; optional backface cull,
// world-space rebase, wireframe overlay). ``wInv`` is the frame's
// world->local inverse, applied only when the soup is world-space.
static void _drawPoly(MHWRender::MUIDrawManager& dm, const WidgetShowcaseData& d,
                      const DrawPoly& pg, const MMatrix& wInv) {
    if (pg.pts.empty() || pg.cnt.empty()) return;
    const bool selOK = d.selected;
    // Per-aspect selection highlight; an unset flag inherits the node-wide
    // self.auto_highlight (_draw_polygons' highlight_fill/highlight_wire
    // default to global_auto_highlight).
    const bool hlFill = (pg.highlightFill < 0) ? d.autoHighlight
                                              : (pg.highlightFill != 0);
    const bool hlWire = (pg.highlightWire < 0) ? d.autoHighlight
                                              : (pg.highlightWire != 0);
    std::vector<MPoint> P = pg.pts;
    if (pg.worldSpace) {
        for (size_t i = 0; i < P.size(); ++i) P[i] = P[i] * wInv;
    }
    const size_t F = pg.cnt.size();
    std::vector<int> off(F, 0);
    for (size_t f = 1; f < F; ++f) off[f] = off[f-1] + pg.cnt[f-1];
    MPoint vp(d.viewPosLocal[0], d.viewPosLocal[1], d.viewPosLocal[2]);
    std::vector<char> faceVisible(F, 1);
    if (pg.cull) {
        for (size_t f = 0; f < F; ++f) {
            int c = pg.cnt[f]; if (c < 3) { faceVisible[f] = 0; continue; }
            MPoint p0 = P[pg.idx[off[f]]];
            MPoint p1 = P[pg.idx[off[f]+1]];
            MPoint p2 = P[pg.idx[off[f]+2]];
            MVector nrm = (p1 - p0) ^ (p2 - p0);
            MVector vd = vp - p0;
            faceVisible[f] = (nrm * vd > 0.0) ? 1 : 0;
        }
    }
    MPointArray tri; MColorArray tcol;
    const bool perCorner = (pg.colorMode != 0);
    const bool tintFill = (selOK && hlFill);
    for (size_t f = 0; f < F; ++f) {
        if (!faceVisible[f]) continue;
        int c = pg.cnt[f]; if (c < 3) continue;
        for (int k = 1; k + 1 < c; ++k) {
            int corner[3] = {0, k, k + 1};
            for (int t = 0; t < 3; ++t) {
                int loc = off[f] + corner[t];
                int vid = pg.idx[loc];
                tri.append(P[vid]);
                if (perCorner) {
                    MColor col;
                    if (pg.colorMode == 1 && f < pg.faceColors.size()) col = pg.faceColors[f];
                    else if (pg.colorMode == 2 && vid < (int)pg.vertexColors.size()) col = pg.vertexColors[vid];
                    else if (pg.colorMode == 3 && loc < (int)pg.faceVertexColors.size()) col = pg.faceVertexColors[loc];
                    tcol.append(tintFill ? _selTint(d.selColor, col) : col);
                }
            }
        }
    }
    if (tri.length() >= 3) {
        dm.beginDrawable();
        // A tint rides on the colors already built (per corner above, or the
        // uniform below), so the soup keeps its own alpha while selected.
        if (perCorner) { dm.mesh(MHWRender::MUIDrawManager::kTriangles, tri, NULL, &tcol); }
        else { dm.setColor(tintFill ? _selTint(d.selColor, pg.uniform) : pg.uniform);
               dm.mesh(MHWRender::MUIDrawManager::kTriangles, tri); }
        dm.endDrawable();
    }
    // wireframe overlay (optional boundary-only; respects cull)
    if (pg.hasWire) {
        std::map<long long, int> edgeCount;
        std::vector<std::pair<int,int> > edges;
        for (size_t f = 0; f < F; ++f) {
            if (!faceVisible[f]) continue;
            int c = pg.cnt[f]; if (c < 2) continue;
            for (int k = 0; k < c; ++k) {
                int a = pg.idx[off[f] + k];
                int b = pg.idx[off[f] + ((k + 1) % c)];
                int lo = a < b ? a : b, hi = a < b ? b : a;
                long long key = (long long)lo * 1000000LL + hi;
                if (edgeCount.find(key) == edgeCount.end()) edges.push_back(std::make_pair(lo, hi));
                edgeCount[key] += 1;
            }
        }
        const MColor wcol = (selOK && hlWire) ? _selTint(d.selColor, pg.wireColor)
                                              : pg.wireColor;
        dm.beginDrawable();
        dm.setColor(wcol);
        dm.setLineWidth((float)pg.wireWidth);
        for (size_t e = 0; e < edges.size(); ++e) {
            int lo = edges[e].first, hi = edges[e].second;
            long long key = (long long)lo * 1000000LL + hi;
            if (pg.wireBoundaryOnly && edgeCount[key] != 1) continue;
            dm.line(P[lo], P[hi]);
        }
        dm.endDrawable();
    }
}

// Whole-pixel point size. VP2 draws fat points through a shader whose size is
// a parameter and caches the instance BY VALUE: every distinct size is a new
// instance (~85 us measured per point), a repeated value is ~free. Continuous
// sizes made every point its own instance -- 56% of a locator's draw cost.
// Rounding bounds the distinct values scene-wide (<= 0.5 px change); the
// interpreted framework rounds identically (draw_buffers.point_pixel_size).
static float _pointPx(float s) { long p = std::lround((double)s); return (float)(p < 1 ? 1 : p); }
// Port of draw_buffers.local_text_pixel_size: an object-space glyph height
// becomes bitmap-font pixels at this depth, clamped to [6, 256]. With no view
// scale (headless / degenerate) the size is taken as pixels, as the framework
// does when local_ppu is None.
static unsigned _textPx(double size, double ppu) {
    if (ppu <= 0.0) return (unsigned)(size < 0.0 ? 0.0 : size);
    double px = size * ppu; if (px < 6.0) px = 6.0; if (px > 256.0) px = 256.0;
    return (unsigned)std::lround(px);
}

void WidgetShowcaseDrawOverride::addUIDrawables(const MDagPath& objPath,
                        MHWRender::MUIDrawManager& dm,
                        const MHWRender::MFrameContext& frameContext,
                        const MUserData* userData) {
    (void)frameContext;
    const WidgetShowcaseData* d = dynamic_cast<const WidgetShowcaseData*>(userData);
    if (!d) return;
    // Framework auto-highlight (MPyLocatorDrawOverride.addUIDrawables'
    // override_color): when selected AND self.auto_highlight, every
    // line/point/text/shape takes the selection color -- its RGB over the
    // element's own alpha, so translucent stays translucent. Polygons decide
    // per aspect, inside _drawPoly.
    const bool hlAll = (d->selected && d->autoHighlight);
    // one world->local inverse per frame; world-space items rebase with it
    const MMatrix wInv = objPath.inclusiveMatrixInverse();
    // replay the drawing FRONT TO BACK -- authoring order is draw order.
    // ONE drawable batch per node (like the interpreted framework): a
    // begin/end pair per item cost 10% of the per-node draw time at N=100.
    dm.beginDrawable();
    for (size_t ci = 0; ci < d->cmds.size(); ++ci) {
        const int i = d->cmds[ci].index;
        switch (d->cmds[ci].slot) {
            case 0: {  // line
                MPoint a = d->lineStart[i], b = d->lineEnd[i];
                if (d->lineWorld[i]) { a = a * wInv; b = b * wInv; }
                dm.setColor(hlAll ? _selTint(d->selColor, d->lineColor[i]) : d->lineColor[i]);
                dm.line(a, b);
            } break;
            case 1: {  // point
                dm.setColor(hlAll ? _selTint(d->selColor, d->pointColor[i]) : d->pointColor[i]);
                dm.setPointSize(_pointPx(d->pointSize[i])); dm.point(d->pointPos[i]);
            } break;
            case 2: {  // text
                dm.setColor(hlAll ? _selTint(d->selColor, d->textColor[i]) : d->textColor[i]);
                dm.setFontSize(_textPx(d->textSize[i], d->localPpu));
                dm.text(d->textPos[i], d->textStr[i]);
            } break;
            case 3: {  // shape
                dm.setColor(hlAll ? _selTint(d->selColor, d->shapeColor[i]) : d->shapeColor[i]);
                const bool fl = d->shapeFilled[i] != 0;
                switch (d->shapeKind[i]) {
                    case 0: dm.sphere(d->shapeCenter[i], d->shapeRadius[i], fl); break;
                    case 1: dm.circle(d->shapeCenter[i], d->shapeAxis[i], d->shapeRadius[i], fl); break;
                    case 2: dm.box(d->shapeCenter[i], MVector(0,1,0), MVector(1,0,0),
                                   d->shapeRadius[i], d->shapeRadius[i], d->shapeRadius[i], fl); break;
                    case 3: dm.cone(d->shapeCenter[i], d->shapeAxis[i], d->shapeRadius[i], d->shapeRadius[i]*2.0, fl); break;
                    case 4: dm.cylinder(d->shapeCenter[i], d->shapeAxis[i], d->shapeRadius[i], d->shapeRadius[i]*2.0, 16, fl); break;
                    default: dm.circle(d->shapeCenter[i], d->shapeAxis[i], d->shapeRadius[i], fl); break;
                }
            } break;
            // polygons open their own batches: close ours around the call
            default: dm.endDrawable(); _drawPoly(dm, *d, d->polys[i], wInv); dm.beginDrawable(); break;
        }
    }
    dm.endDrawable();
}

MStatus initializePlugin(MObject obj) {
    MFnPlugin plugin(obj, "Eric Vignola", "1.0.0+761c9c9a4d2d", "Any");
    MStatus st = plugin.registerNode(
        "widgetShowcase", WidgetShowcase::id, WidgetShowcase::creator, WidgetShowcase::initialize,
        MPxNode::kLocatorNode, &WidgetShowcase::drawDbClassification);
    if (!st) return st;
    return MHWRender::MDrawRegistry::registerDrawOverrideCreator(
        WidgetShowcase::drawDbClassification, WidgetShowcase::drawRegistrantId, WidgetShowcaseDrawOverride::creator);
}
MStatus uninitializePlugin(MObject obj) {
    MFnPlugin plugin(obj);
    MHWRender::MDrawRegistry::deregisterDrawOverrideCreator(
        WidgetShowcase::drawDbClassification, WidgetShowcase::drawRegistrantId);
    return plugin.deregisterNode(WidgetShowcase::id);
}

#endif  // !MPYNODE_PROBE

#ifdef MPYNODE_PROBE
// Standalone buffer dumper: reads a frame file (argv[1]) describing each
// frame's inputs, runs computeBuffers, prints the draw buffers as JSON.
// Compile with -DMPYNODE_PROBE as an executable; links OpenMaya+Foundation
// only. Used to numerically compare the ported draw math (incl. polygons)
// against the original Python evaluateDrawItems().
static void _emitPts(const std::vector<MPoint>& v) {
    printf("[");
    for (size_t i = 0; i < v.size(); ++i)
        printf("%s[%.9g,%.9g,%.9g]", i?",":"", v[i].x, v[i].y, v[i].z);
    printf("]");
}
static void _emitVecs(const std::vector<MVector>& v) {
    printf("[");
    for (size_t i = 0; i < v.size(); ++i)
        printf("%s[%.9g,%.9g,%.9g]", i?",":"", v[i].x, v[i].y, v[i].z);
    printf("]");
}
static void _emitCols(const std::vector<MColor>& v) {
    printf("[");
    for (size_t i = 0; i < v.size(); ++i)
        printf("%s[%.9g,%.9g,%.9g,%.9g]", i?",":"", v[i].r, v[i].g, v[i].b, v[i].a);
    printf("]");
}
static void _emitCol(const MColor& c) {
    printf("[%.9g,%.9g,%.9g,%.9g]", c.r, c.g, c.b, c.a);
}
template<class T> static void _emitNums(const std::vector<T>& v) {
    printf("[");
    for (size_t i = 0; i < v.size(); ++i)
        printf("%s%.9g", i?",":"", (double)v[i]);
    printf("]");
}
static void _emitStrs(const std::vector<MString>& v) {
    printf("[");
    for (size_t i = 0; i < v.size(); ++i)
        printf("%s\"%s\"", i?",":"", v[i].asChar());
    printf("]");
}
static void _emitCmds(const std::vector<DrawCmd>& v) {
    static const char* kSlot[] = {"lines","points","text","shapes","polygons"};
    printf("[");
    for (size_t i = 0; i < v.size(); ++i) {
        int s = v[i].slot; if (s < 0 || s > 4) s = 4;
        printf("%s[\"%s\",%d]", i?",":"", kSlot[s], v[i].index);
    }
    printf("]");
}
static void _emitPolys(const std::vector<DrawPoly>& v) {
    printf("[");
    for (size_t i = 0; i < v.size(); ++i) {
        const DrawPoly& pg = v[i];
        printf("%s{", i?",":"");
        printf("\"points\":"); _emitPts(pg.pts); printf(",");
        printf("\"indices\":"); _emitNums(pg.idx); printf(",");
        printf("\"counts\":"); _emitNums(pg.cnt); printf(",");
        printf("\"colorMode\":%d,", pg.colorMode);
        printf("\"uniform\":"); _emitCol(pg.uniform); printf(",");
        printf("\"faceColors\":"); _emitCols(pg.faceColors); printf(",");
        printf("\"vertexColors\":"); _emitCols(pg.vertexColors); printf(",");
        printf("\"faceVertexColors\":"); _emitCols(pg.faceVertexColors); printf(",");
        printf("\"cull\":%d,", pg.cull?1:0);
        printf("\"wire\":%d,", pg.hasWire?1:0);
        printf("\"wireColor\":"); _emitCol(pg.wireColor); printf(",");
        printf("\"wireWidth\":%.9g,", pg.wireWidth);
        printf("\"wireBoundaryOnly\":%d,", pg.wireBoundaryOnly?1:0);
        printf("\"worldSpace\":%d,", pg.worldSpace?1:0);
        printf("\"highlightFill\":%d,", pg.highlightFill?1:0);
        printf("\"highlightWire\":%d,", pg.highlightWire?1:0);
        printf("\"preciseHover\":%d", pg.preciseHover?1:0);
        printf("}");
    }
    printf("]");
}
static void _setInput(WidgetShowcaseInputs& f, const std::string& n, double v) {
    if (n == "in_preset") f.in_preset = (short)v;
    else { (void)f; (void)n; (void)v; }
}
static std::vector<WidgetShowcaseInputs> _readFrames(const char* path) {
    std::vector<WidgetShowcaseInputs> out;
    FILE* fp = fopen(path, "r"); if (!fp) return out;
    char tok[256]; WidgetShowcaseInputs cur; bool inFrame = false; (void)inFrame;
    while (fscanf(fp, "%255s", tok) == 1) {
        std::string k(tok);
        if (k == "FRAME") { cur = WidgetShowcaseInputs(); inFrame = true; }
        else if (k == "ENDFRAME") { out.push_back(cur); inFrame = false; }
        else if (k == "TIME") { double x; if(fscanf(fp, "%lf", &x)==1) cur.timeVal = x; }
        else if (k == "WALL") { double x; if(fscanf(fp, "%lf", &x)==1) cur.wallClock = x; }
        else if (k == "STATE") { int a,b,c; if(fscanf(fp, "%d %d %d", &a,&b,&c)==3){ cur.selected=a; cur.isLead=b; cur.hovered=c; } }
        else if (k == "SELCOL") { float r,g,b,a; if(fscanf(fp, "%f %f %f %f", &r,&g,&b,&a)==4){ cur.selColor[0]=r; cur.selColor[1]=g; cur.selColor[2]=b; cur.selColor[3]=a; } }
        else if (k == "IN") { char nm[128]; double x; if(fscanf(fp, "%127s %lf", nm, &x)==2) _setInput(cur, std::string(nm), x); }
    }
    fclose(fp); return out;
}
int main(int argc, char** argv) {
    std::vector<WidgetShowcaseInputs> frames;
    if (argc > 1) frames = _readFrames(argv[1]);
    if (frames.empty()) { WidgetShowcaseInputs f; frames.push_back(f); }
    printf("[");
    for (size_t k = 0; k < frames.size(); ++k) {
        WidgetShowcaseData data; WidgetShowcase_computeBuffers(frames[k], data);
        printf("%s{", k?",":"");
        printf("\"time\":%.9g,", frames[k].timeVal);
        printf("\"cmds\":");      _emitCmds(data.cmds);     printf(",");
        printf("\"lineStart\":"); _emitPts(data.lineStart); printf(",");
        printf("\"lineEnd\":");   _emitPts(data.lineEnd);   printf(",");
        printf("\"lineColor\":"); _emitCols(data.lineColor); printf(",");
        printf("\"lineWorld\":"); _emitNums(data.lineWorld); printf(",");
        printf("\"pointPos\":");  _emitPts(data.pointPos);  printf(",");
        printf("\"pointColor\":");_emitCols(data.pointColor);printf(",");
        printf("\"pointSize\":"); _emitNums(data.pointSize); printf(",");
        printf("\"textPos\":");   _emitPts(data.textPos);   printf(",");
        printf("\"textStr\":");   _emitStrs(data.textStr);  printf(",");
        printf("\"textColor\":"); _emitCols(data.textColor);printf(",");
        printf("\"textSize\":");  _emitNums(data.textSize); printf(",");
        printf("\"shapeKind\":"); _emitNums(data.shapeKind);printf(",");
        printf("\"shapeCenter\":");_emitPts(data.shapeCenter);printf(",");
        printf("\"shapeRadius\":");_emitNums(data.shapeRadius);printf(",");
        printf("\"shapeAxis\":"); _emitVecs(data.shapeAxis); printf(",");
        printf("\"shapeColor\":");_emitCols(data.shapeColor);printf(",");
        printf("\"shapeFilled\":");_emitNums(data.shapeFilled);printf(",");
        printf("\"polys\":"); _emitPolys(data.polys);
        printf("}");
    }
    printf("]\n");
    return 0;
}
#endif